/* ============================================================
   Fluxer Theme: Kaly OLED Neon Black Safe V4.3.42
   Objectif :
   - base V4.3.38 conservée dans l'esprit et la structure
   - noir OLED pur en fond
   - interface blanc / gris très opaque façon terminal OLED
   - aucun rendu violet, rose, bleu, cyan ou coloré
   - cadres, boutons, scrollbars, modales, messages, mentions
   - logo Fluxer remplacé par logo SVG custom blanc
   - cercle blanc/gris autour du logo, sans glow coloré
   - nagbar sobre monochrome
   - badges guild / voice propres
   - halo avatar monochrome
   - highlight de salons sobre, lisible, sans modifier le texte
   ============================================================ */

:root {
  /* =========================
     Palette terminal noir/blanc
     ========================= */

  --term-black-0: #000000;
  --term-black-1: #030303;
  --term-black-2: #060606;
  --term-black-3: #090909;
  --term-black-4: #0d0d0d;
  --term-black-5: #111111;
  --term-black-6: #171717;
  --term-black-7: #1d1d1d;

  --term-white-0: #ffffff;
  --term-white-1: #f5f5f5;
  --term-white-2: #e8e8e8;
  --term-white-3: #d6d6d6;
  --term-white-4: #bcbcbc;
  --term-white-5: #969696;
  --term-white-6: #707070;

  --term-glass-weak: rgba(255, 255, 255, 0.035);
  --term-glass-soft: rgba(255, 255, 255, 0.055);
  --term-glass-mid: rgba(255, 255, 255, 0.085);
  --term-glass-strong: rgba(255, 255, 255, 0.14);
  --term-glass-heavy: rgba(255, 255, 255, 0.22);

  --term-border: rgba(255, 255, 255, 0.13);
  --term-border-soft: rgba(255, 255, 255, 0.075);
  --term-border-strong: rgba(255, 255, 255, 0.28);

  --term-bg-left: var(--term-black-0);
  --term-bg-left-soft: var(--term-black-2);

  --term-bg-main: var(--term-black-3);
  --term-bg-main-soft: var(--term-black-5);

  --term-sidebar: rgba(5, 5, 5, 0.94);
  --term-sidebar-soft: rgba(10, 10, 10, 0.94);

  --term-panel: rgba(12, 12, 12, 0.88);
  --term-panel-soft: rgba(18, 18, 18, 0.9);
  --term-panel-hover: rgba(28, 28, 28, 0.92);
  --term-panel-active: rgba(40, 40, 40, 0.96);

  --term-modal: rgba(14, 14, 14, 0.98);
  --term-modal-side: rgba(6, 6, 6, 0.98);

  --term-input: rgba(0, 0, 0, 0.96);
  --term-input-soft: rgba(8, 8, 8, 0.98);

  --term-text: var(--term-white-1);
  --term-text-soft: var(--term-white-3);
  --term-muted: var(--term-white-4);
  --term-muted-dark: var(--term-white-6);

  --term-shadow-deep: 0 18px 50px rgba(0, 0, 0, 0.58);
  --term-shadow-panel: 0 10px 32px rgba(0, 0, 0, 0.36);
  --term-glow-white: 0 0 24px rgba(255, 255, 255, 0.08);
  --term-glow-white-soft: 0 0 18px rgba(255, 255, 255, 0.045);

  --term-radius-sm: 8px;
  --term-radius-md: 12px;
  --term-radius-lg: 16px;

  /* =========================
     Bandeau Kaly terminal
     ========================= */

  --kaly-nagbar-bg: #050505;
  --kaly-nagbar-text: #f4f4f4;
  --kaly-nagbar-border: rgba(255, 255, 255, 0.18);

  /* =========================
     Logo custom Kaly terminal
     ========================= */

  --kaly-logo-circle: rgba(255, 255, 255, 0.78);
  --kaly-logo-circle-hover: #ffffff;
  --kaly-logo-bg: rgba(255, 255, 255, 0.035);
  --kaly-logo-bg-hover: rgba(255, 255, 255, 0.075);

  --kaly-logo-ring-size: 3.25rem;
  --kaly-logo-icon-size: 2.55rem;

  --kaly-fluxer-logo: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%201100%201083%22%20role%3D%22img%22%20aria-label%3D%22Logo%22%20fill%3D%22none%22%3E%3Cpath%20fill%3D%22white%22%20fill-rule%3D%22evenodd%22%20clip-rule%3D%22evenodd%22%20d%3D%22%20M%20354%2025%20L%20348%2029%20L%20247%20151%20L%20184%20236%20L%20159%20275%20L%20137%20313%20L%20110%20366%20L%2091%20409%20L%2072%20459%20L%2055%20515%20L%2042%20569%20L%2035%20609%20L%2029%20653%20L%2024%20718%20L%2024%20763%20L%2029%20836%20L%2032%20840%20L%2066%20839%20L%2096%20835%20L%20123%20829%20L%20167%20813%20L%20194%20800%20L%20247%20771%20L%20278%20758%20L%20311%20750%20L%20331%20749%20L%20347%20751%20L%20358%20754%20L%20368%20759%20L%20379%20768%20L%20379%20771%20L%20364%20786%20L%20357%20796%20L%20348%20815%20L%20344%20829%20L%20340%20864%20L%20340%20923%20L%20336%20950%20L%20331%20967%20L%20322%20987%20L%20314%20999%20L%20294%201020%20L%20283%201028%20L%20293%201033%20L%20311%201037%20L%20349%201036%20L%20373%201030%20L%20389%201024%20L%20404%201016%20L%20420%201004%20L%20437%20985%20L%20448%20966%20L%20453%20953%20L%20459%20929%20L%20462%20901%20L%20467%20878%20L%20480%20850%20L%20484%20848%20L%20486%20896%20L%20495%20936%20L%20502%20957%20L%20523%201008%20L%20539%201039%20L%20551%201058%20L%20569%201027%20L%20581%201002%20L%20594%20971%20L%20605%20939%20L%20614%20897%20L%20616%20872%20L%20615%20848%20L%20618%20847%20L%20622%20852%20L%20633%20877%20L%20637%20893%20L%20642%20931%20L%20649%20957%20L%20658%20976%20L%20666%20988%20L%20684%201006%20L%20700%201017%20L%20718%201026%20L%20752%201036%20L%20790%201037%20L%20813%201031%20L%20818%201027%20L%20805%201018%20L%20784%20995%20L%20773%20975%20L%20767%20958%20L%20761%20922%20L%20760%20849%20L%20757%20830%20L%20751%20810%20L%20744%20796%20L%20736%20785%20L%20721%20771%20L%20721%20769%20L%20727%20763%20L%20746%20753%20L%20760%20750%20L%20779%20749%20L%20806%20753%20L%20826%20759%20L%20852%20770%20L%20929%20810%20L%20980%20829%20L%201007%20835%20L%201035%20839%20L%201068%20840%20L%201070%20838%20L%201075%20783%20L%201075%20700%20L%201071%20649%20L%201065%20605%20L%201053%20542%20L%201038%20485%20L%201018%20426%20L%20993%20366%20L%20973%20325%20L%20953%20289%20L%20907%20217%20L%20842%20132%20L%20751%2026%20L%20745%2024%20L%20734%2024%20L%20728%2026%20L%20691%2069%20L%20666%20102%20L%20644%20135%20L%20623%20171%20L%20606%20206%20L%20591%20244%20L%20585%20244%20L%20561%20238%20L%20539%20238%20L%20512%20244%20L%20510%20242%20L%20498%20208%20L%20482%20173%20L%20459%20133%20L%20440%20104%20L%20415%2071%20L%20375%2026%20L%20369%2024%20Z%20M%20719%20451%20L%20737%20451%20L%20755%20454%20L%20769%20459%20L%20793%20473%20L%20807%20486%20L%20820%20504%20L%20831%20530%20L%20835%20552%20L%20834%20579%20L%20830%20595%20L%20821%20615%20L%20810%20631%20L%20794%20647%20L%20778%20658%20L%20756%20667%20L%20732%20671%20L%20713%20670%20L%20693%20665%20L%20679%20659%20L%20659%20646%20L%20645%20632%20L%20633%20615%20L%20623%20592%20L%20619%20571%20L%20619%20552%20L%20622%20534%20L%20626%20522%20L%20634%20506%20L%20644%20492%20L%20661%20475%20L%20674%20466%20L%20693%20457%20Z%20M%20366%20451%20L%20384%20451%20L%20401%20454%20L%20427%20465%20L%20440%20474%20L%20453%20486%20L%20464%20500%20L%20471%20512%20L%20478%20530%20L%20482%20550%20L%20482%20572%20L%20477%20595%20L%20470%20611%20L%20455%20633%20L%20434%20652%20L%20416%20662%20L%20398%20668%20L%20376%20671%20L%20354%20669%20L%20337%20664%20L%20324%20658%20L%20305%20645%20L%20293%20633%20L%20280%20614%20L%20271%20593%20L%20267%20571%20L%20267%20551%20L%20271%20530%20L%20281%20507%20L%20293%20490%20L%20307%20476%20L%20321%20466%20L%20340%20457%20Z%20%22%2F%3E%3C%2Fsvg%3E");

  /* =========================
     Badges guild terminal
     ========================= */

  --kaly-guild-badge-bg: linear-gradient(135deg, #f7f7f7 0%, #b8b8b8 44%, #3a3a3a 100%);
  --kaly-guild-badge-bg-active: linear-gradient(135deg, #ffffff 0%, #d8d8d8 46%, #5a5a5a 100%);
  --kaly-guild-badge-text: #000000;
  --kaly-guild-badge-ring: #000000;
  --kaly-guild-badge-glow: rgba(255, 255, 255, 0.18);

  /* =========================
     Variables Fluxer mappées
     ========================= */

  --background-tertiary: var(--term-bg-left);

  --background-secondary: var(--term-sidebar);
  --background-secondary-alt: var(--term-sidebar-soft);
  --background-secondary-lighter: var(--term-panel-soft);

  --background-primary: var(--term-bg-main);
  --background-textarea: var(--term-input);

  --background-header-primary: rgba(3, 3, 3, 0.96);
  --background-header-primary-hover: var(--term-panel);
  --background-header-secondary: var(--term-bg-left-soft);

  --background-modifier-hover: rgba(255, 255, 255, 0.055);
  --background-modifier-selected: var(--term-panel-active);
  --background-modifier-accent: rgba(255, 255, 255, 0.08);
  --background-modifier-accent-focus: rgba(255, 255, 255, 0.24);

  --brand-primary: #ffffff;
  --brand-secondary: #bdbdbd;
  --brand-primary-light: #f0f0f0;

  --accent-primary: #ffffff;
  --focus-primary: #ffffff;

  --text-primary: var(--term-text);
  --text-secondary: var(--term-text-soft);
  --text-tertiary: var(--term-muted);
  --text-primary-muted: var(--term-muted);
  --text-tertiary-muted: var(--term-muted-dark);
  --text-tertiary-secondary: var(--term-muted-dark);

  --text-chat: var(--term-text);
  --text-chat-muted: var(--term-muted);
  --text-link: #ffffff;

  --guild_list-foreground: var(--term-bg-left);

  /* =========================
     Apparence / Markdown
     ========================= */

  --bg-primary: var(--term-bg-main);
  --bg-secondary: var(--term-panel);
  --bg-tertiary: var(--term-bg-left);
  --bg-hover: var(--term-panel-hover);
  --bg-active: var(--term-panel-active);

  --bg-code: #000000;
  --bg-code-block: #000000;
  --bg-blockquote: rgba(16, 16, 16, 0.9);
  --bg-table-header: rgba(0, 0, 0, 0.98);
  --bg-table-row-odd: rgba(8, 8, 8, 0.9);
  --bg-table-row-even: rgba(14, 14, 14, 0.9);

  --markup-mention-text: #ffffff;
  --markup-interactive-hover-text: #ffffff;

  --button-outline-border: rgba(255, 255, 255, 0.2);
  --border-color: var(--term-border-soft);

  --form-surface-background: var(--term-panel);
  --surface-interactive-hover-bg: var(--term-panel-hover);
  --surface-interactive-selected-bg: var(--term-panel-active);
  --surface-interactive-selected-color: var(--term-text);

  --scrollbar-thumb-bg: #4a4a4a;
  --scrollbar-thumb-bg-hover: #f2f2f2;
  --scrollbar-track-bg: #000000;

  color-scheme: dark;
}

/* =========================
   Animations
   ========================= */

@keyframes term-bg-drift {
  0% {
    background-position: 0% 0%, 100% 0%, 50% 50%;
  }

  50% {
    background-position: 12% 4%, 88% 8%, 50% 50%;
  }

  100% {
    background-position: 0% 0%, 100% 0%, 50% 50%;
  }
}

@keyframes term-button-scan {
  0% {
    background-position: 0% 50%;
  }

  100% {
    background-position: 100% 50%;
  }
}

@keyframes term-caret-flicker {
  0%, 100% {
    opacity: 0.85;
  }

  50% {
    opacity: 0.55;
  }
}

/* =========================
   Base
   ========================= */

html,
body,
#root {
  background-color: var(--term-bg-main) !important;
  color: var(--term-text) !important;
}

body {
  background:
    radial-gradient(circle at 12% 0%, rgba(255, 255, 255, 0.035), transparent 32rem),
    radial-gradient(circle at 86% 4%, rgba(255, 255, 255, 0.022), transparent 30rem),
    linear-gradient(135deg, #000000 0%, #070707 48%, #020202 100%) !important;
  background-attachment: fixed !important;
  animation: term-bg-drift 22s ease-in-out infinite;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 999999;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.012) 1px, transparent 1px);
  background-size: 24px 24px;
  mask-image: radial-gradient(circle at center, black 0%, transparent 76%);
}

main {
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.028), transparent 34rem),
    linear-gradient(180deg, rgba(8, 8, 8, 0.98), rgba(0, 0, 0, 0.985)) !important;
}

/* =========================
   Colonnes latérales
   ========================= */

aside {
  background-color: var(--term-sidebar) !important;
  border-right: 1px solid rgba(255, 255, 255, 0.08) !important;
  backdrop-filter: blur(18px) saturate(110%);
  -webkit-backdrop-filter: blur(18px) saturate(110%);
}

aside:first-child {
  background:
    linear-gradient(180deg, rgba(0, 0, 0, 0.98), rgba(7, 7, 7, 0.98)) !important;
  box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.08);
}

/* =========================
   Panneaux ciblés
   ========================= */

section,
article,
nav {
  border-color: rgba(255, 255, 255, 0.07) !important;
}

[class*="card"],
[class*="Card"],
[class*="panel"],
[class*="Panel"],
[class*="surface"],
[class*="Surface"] {
  border-color: rgba(255, 255, 255, 0.1) !important;
}

/* =========================
   Modales / paramètres / profils
   ========================= */

dialog {
  background:
    linear-gradient(180deg, rgba(18, 18, 18, 0.98), rgba(5, 5, 5, 0.98)) !important;
  color: var(--term-text) !important;
  border: 1px solid var(--term-border) !important;
  border-radius: var(--term-radius-lg) !important;
  box-shadow:
    var(--term-shadow-deep),
    var(--term-glow-white-soft) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transition:
    background-color 120ms ease,
    border-color 120ms ease,
    box-shadow 120ms ease !important;
}

.modal-backdrop [role="dialog"] {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.modal-backdrop [class*="Modal_focusLock"],
.modal-backdrop [class*="Modal_surface"] {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.modal-backdrop [class*="Modal_root"] {
  background:
    linear-gradient(180deg, rgba(18, 18, 18, 0.98), rgba(5, 5, 5, 0.98)) !important;
  color: var(--term-text) !important;
  border: 1px solid var(--term-border) !important;
  border-radius: var(--term-radius-lg) !important;
  box-shadow:
    var(--term-shadow-deep),
    var(--term-glow-white-soft) !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  overflow: hidden !important;
  pointer-events: all !important;
}

dialog:not([open]),
.modal-backdrop [role="dialog"][hidden],
.modal-backdrop [role="dialog"][aria-hidden="true"],
.modal-backdrop [role="dialog"][data-state="closed"],
.modal-backdrop [role="dialog"][data-closing="true"] {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: none !important;
}

[class*="Modal_modalBackdrop"],
[class*="modalBackdrop"],
[class*="ModalBackdrop"] {
  background: rgba(0, 0, 0, 0.62) !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

[class*="Modal_backdropCentered"],
[class*="backdropCentered"],
[class*="BackdropCentered"] {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.modal-backdrop {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.modal-backdrop[aria-hidden="true"] {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: none !important;
}

[class*="Modal_layer"][style*="visibility: hidden"],
[class*="Modal_layer"][style*="visibility:hidden"],
[class*="Modal_layer"][style*="opacity: 0"],
[class*="Modal_layer"][style*="opacity:0"] {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: none !important;
}

[class*="Popout"][aria-hidden="true"],
[class*="popout"][aria-hidden="true"],
[class*="Popout"][data-state="closed"],
[class*="popout"][data-state="closed"],
[class*="Popout"][data-closing="true"],
[class*="popout"][data-closing="true"] {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: none !important;
  animation: none !important;
}

/* =========================
   Champs texte
   ========================= */

input,
textarea,
select {
  background:
    linear-gradient(180deg, rgba(5, 5, 5, 0.98), rgba(0, 0, 0, 0.98)) !important;
  color: var(--term-text) !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  border-radius: var(--term-radius-md) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035),
    0 8px 24px rgba(0, 0, 0, 0.22) !important;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

textarea {
  min-height: 46px !important;
  line-height: 20px !important;
  padding: 13px 14px !important;
  text-align: left !important;
  box-sizing: border-box !important;
}

input:hover,
textarea:hover,
select:hover {
  border-color: rgba(255, 255, 255, 0.28) !important;
}

input::placeholder,
textarea::placeholder {
  color: var(--term-muted-dark) !important;
}

input:focus,
textarea:focus,
select:focus {
  background-color: var(--term-input-soft) !important;
  border-color: #ffffff !important;
  outline: none !important;
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.16),
    0 0 22px rgba(255, 255, 255, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.04) !important;
}

/* =========================
   Liens
   ========================= */

a {
  color: #ffffff !important;
  text-decoration-color: rgba(255, 255, 255, 0.34) !important;
  text-underline-offset: 3px;
  transition:
    color 140ms ease,
    text-decoration-color 140ms ease,
    text-shadow 140ms ease;
}

a:hover {
  color: #ffffff !important;
  text-decoration-color: rgba(255, 255, 255, 0.82) !important;
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.22);
}

/* =========================
   Boutons
   ========================= */

button {
  color: var(--term-text) !important;
  font-weight: 700;
  letter-spacing: 0.01em;
  border-radius: var(--term-radius-md) !important;
  border-color: rgba(255, 255, 255, 0.16) !important;
  transition:
    transform 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease,
    background-color 140ms ease,
    filter 140ms ease;
}

button:hover {
  border-color: rgba(255, 255, 255, 0.34) !important;
  transform: translateY(-1px);
  box-shadow:
    0 10px 24px rgba(0, 0, 0, 0.28),
    var(--term-glow-white) !important;
}

button:active {
  transform: translateY(0);
  filter: brightness(0.94);
}

button:disabled {
  opacity: 0.5;
  transform: none;
  box-shadow: none !important;
}

button[type="submit"],
button[data-primary="true"] {
  background:
    linear-gradient(135deg, #ffffff, #d4d4d4, #8f8f8f) !important;
  background-size: 180% 180% !important;
  color: #000000 !important;
  border-color: rgba(255, 255, 255, 0.48) !important;
  box-shadow:
    0 10px 28px rgba(255, 255, 255, 0.075),
    inset 0 1px 0 rgba(255, 255, 255, 0.7) !important;
}

button[type="submit"]:hover,
button[data-primary="true"]:hover {
  animation: term-button-scan 900ms ease forwards;
  box-shadow:
